  1024	                self.parser.state = .escape;
  1025	                self.parser.clear();
  1026	                offset += 1;
  1027	                offset += self.consumeUntilGround(input[offset..], until, u);
  1028	                if (comptime until) if (self.untilReached(u, input.ptr + offset)) return offset;
  1029	                if (offset >= input.len) return input.len;
  1030	            }
