  1035	        /// Returns the number of bytes consumed from the provided input.
  1036	        inline fn consumeUntilGround(
  1037	            self: *Self,
  1038	            input: []const u8,
  1039	            comptime until: bool,
  1040	            u: Until.Arg(until),
